def _convert_image(self, image):
    """
    Convert the image to a numpy array of dtype uint8.

    Args:
        image (ndarray): a numpy array of shape (H, W, C) in the range [0, 255].

    Returns:
        ndarray. The converted image with dtype of uint8.
    """
    image = np.asarray(image, dtype=np.uint8)
    if image.ndim == 2:
        image = np.expand_dims(image, axis=2)
    if image.shape[2] == 4:
        image = image[:, :, :3]
    return image

