def simple_test(self, x, img_metas, **kwargs):
    """Test without augment."""
    assert self.with_neck, 'BBoxHead needs a neck, but received None.'
    x = self.neck(x)
    if self.with_shared_head:
        x = self.shared_head(x)
    else:
        x = self.bbox_head(x)
    bbox_inputs = x
    bbox_outputs = self.bbox_head.get_bboxes(
        *bbox_inputs, img_metas=img_metas, **kwargs)
    return bbox_outputs

def aug_test(self, x, img_metas, **kwargs):
    """Test with augmentations."""
    assert self.with_neck, 'BBoxHead needs a neck, but received None.'
    x = self.neck(x)
    if self.with_shared_head:
        x = self.shared_head(x)
    else:
        x = self.bbox_head(x)
    bbox_inputs = x
    bbox_outputs = self.bbox_head.get_bboxes(
        *bbox_inputs, img_metas=img_metas, **kwargs)
    return bbox_outputs

def get_bboxes(self, *args, **kwargs):
    """Wrapper of bbox head forward function."""
    if self.test_cfg.mode == 'whole':
        return self.simple_test(*args, **kwargs)
    elif self.test_cfg.mode == 'aug':
        return self.aug_test(*args, **kwargs)
    else:
        raise NotImplementedError

