def _wrap(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return _trace(func, args, kwargs)(*args, **kwargs)

    return wrapped

if isinstance(func, torch.nn.Module):
    return _wrap(func.forward)
else:
    return _wrap(func)

