def track_linear(fn, mean, cov):
  """Apply function `fn` to a set of means and covariances, ala a Kalman filter.

  This is the linear or isotropic variant of track_linearize, as we're still
  linearizing a Gaussian through `fn`, but the input and output Gaussians are
  all isotropic and are only represented by a single scalar `scale` (which is
  the variance of the Gaussian).

  Args:
    fn: A function that can be applied to a tensor.
    mean: a tensor of Gaussian means, where the last dimension is the axis.
    cov: a tensor of covariances, where the last two axes are the dimensions.

  Returns:
    fn_mean: the transformed means.
    fn_cov: the transformed covariances.
  """
  if (len(mean.shape) + len(cov.shape))!= 2:
    raise ValueError('cov must be non-diagonal')
  d = mean.shape[-1]
  mean_fn, lin_fn = jax.linearize(fn, mean)
  scale = jnp.sqrt(jnp.sum(cov, axis=-1))
  fn_mean = mean_fn + lin_fn(scale)
  fn_cov = scale ** 2
  return fn_mean, fn_cov

