def safe_div(x, y):
  """Division with safeguards against divide-by-zero."""
  return jnp.where(
      jnp.isfinite(x) & jnp.isfinite(y) & (y!= 0), x / y, 0.0
  )


def safe_sqrt(x):
  """Square root with safeguards against negative numbers."""
  return jnp.where(x >= 0, jnp.sqrt(x), 0.0)


def safe_log(x):
  """Natural logarithm with safeguards against negative numbers."""
  return jnp.where(x > 0, jnp.log(x), 0.0)


